//! 🧪️ Original job loans preserve one actual cancellation, whole ValueError and conserved five-axis receipts.
use semio_framework_plugin_reactor_context::*;
use semio_framework_job::StepBudget;
use semio_framework_value::{ValueError, ValueRefusalKind, RetainedCloneProgress};
use semio_framework_actor::{OriginalActorInput, ActorGuestPhase, RetainedTurnInput};
use semio_framework_value::RetainedCloneGrant;
use semio_framework_value::retirement::controlled::ControlledRetirement;
#[doc(hidden)]
pub fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_guest_job_loan_retains_whole_value_error_and_actual_context(){
 let original=RetainedTurnInput{operation:71,generation:3,epoch:19,grant:RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128}};let policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};let((source,error),source_heap)=observe(||{let mut source=Vec::with_capacity(97);source.extend_from_slice(&[81,82,83]);(source,ValueError::new(ValueRefusalKind::AllocationFailed,"whole original job cause 源"))});let source_pointer=source.as_ptr();let cause_pointer=error.message.as_ptr();let mut error=Some(error);let mut host=OriginalActorInput::new(source,original).ok().unwrap();let mut guest=OriginalActorGuestEntry::new();let provider_law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../🔨️modules/🎭️actor/🎟️retained-turn/💼️job/🤝️provider/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();assert_eq!(serde_json::to_value(original).unwrap(),provider_law["request"]["input"]);let mut provider=semio_framework_plugin_reactor_jobs::RegisteredOriginalActorJobs::borrow_original(original.operation,original.generation);let mut incoming=original;let mut allocated=source_heap.0;let mut released=source_heap.1;
 loop{let checked=host.checkout_guest(policy).unwrap().unwrap();let(call,heap)=observe(||guest.admit_step(checked));let receipt=call.receipt().unwrap();let ready=call.result.unwrap().ready;assert_eq!(heap,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));allocated+=heap.0;released+=heap.1;host.receive_guest(receipt,if ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending}).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();if ready{break}}
 let(mut output,system)=observe(||{let mut bytes=Vec::with_capacity(77);bytes.extend_from_slice(&[91,92,93]);Some(bytes)});allocated+=system.0;released+=system.1;let output_pointer=output.as_ref().unwrap().as_ptr();
 for turn in 0..2{let checked=host.checkout_guest(policy).unwrap().unwrap();let mut recipient=Default::default();let(call,system)=observe(||guest.dispatch_job_step(11,checked,StepBudget::new(11,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,|cx|{assert_eq!(turn,0);cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);Ok(Some(semio_framework_actor::OriginalJobStep::Done(output.take().unwrap())))},|held,_cx|{assert_eq!(turn,1);let semio_framework_actor::OriginalJobStep::Done(bytes)=held else{panic!("original output variant changed")};assert_eq!(bytes.as_ptr(),output_pointer);Ok(false)}));assert!(matches!(call.result,Ok(None)));assert_eq!(system,(0,0));assert_eq!(call.work_units_spent,u64::from(turn==0));assert_eq!(guest.original_job_output_identity(),Some((11,71,3)));let semio_framework_actor::OriginalJobStep::Done(bytes)=guest.original_job_output().unwrap()else{panic!("original output lost its source")};assert_eq!(bytes.as_ptr(),output_pointer);host.receive_guest(call.receipt().unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();}
 let(mut admission,system)=observe(||{let mut kind=String::with_capacity(31);kind.push_str("actual.unknown.source");let mut bytes=Vec::with_capacity(43);bytes.extend_from_slice(&[11,12,13]);Some(semio_framework_actor::OriginalJobSource{job:72,kind,input:Some(bytes),checkpoint:None})});allocated+=system.0;released+=system.1;
 for turn in 0..2{let checked=host.checkout_guest(policy).unwrap().unwrap();let mut recipient=Default::default();let(call,system)=observe(||guest.dispatch_job_start_step(checked,StepBudget::new(11,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,&mut admission,|source,cx|semio_framework_plugin_reactor_jobs::abi::start(source,cx)));assert_eq!(system,(0,0));assert_eq!(call.result.unwrap(),turn==1);host.receive_guest(checked.return_original(call.receipt_spent).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();}assert!(admission.is_none());assert_eq!(semio_framework_plugin_reactor_jobs::next_owned_job(71,3),Some(72));assert_eq!(semio_framework_plugin_reactor_jobs::next_owned_job(71,4),None);
 let checked=host.checkout_guest(policy).unwrap().unwrap();let mut recipient=Default::default();let mut wrong=semio_framework_plugin_reactor_jobs::RegisteredOriginalActorJobs::borrow_original(original.operation,original.generation+1);let before=incoming.grant;let(call,system)=observe(||guest.close_jobs_step(checked,StepBudget::new(11,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,&mut wrong));assert_eq!(serde_json::to_value(call.result.is_err()).unwrap(),provider_law["wrongProviderRefusedBeforeWork"]);assert_eq!(serde_json::to_value([system.0,system.1]).unwrap(),provider_law["wrongProviderHeap"]);assert_eq!(call.input,checked);assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert_eq!(guest.original_job_output().and_then(|output|match output{semio_framework_actor::OriginalJobStep::Done(bytes)=>Some(bytes.as_ptr()),_=>None}),Some(output_pointer));assert_eq!(semio_framework_plugin_reactor_jobs::next_owned_job(71,3),Some(provider_law["sameActualRegisteredJob"].as_u64().unwrap()));assert_eq!(semio_framework_plugin_reactor_jobs::original_job_is_cancelled(72),Some(false));host.receive_guest(call.receipt().unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();assert_eq!(parent.remaining,before);incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();

 let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:3,..policy}).unwrap().unwrap();let mut spent=Default::default();let mut witness=std::ptr::null();let(call,heap)=observe(||guest.dispatch_value_step(checked,StepBudget::new(11,u64::MAX,checked.grant),&mut spent,semio_framework_job::logical_now_us,|cx|{witness=cx.borrowed_original_cancel_token()?as*const _;let original=host.original().unwrap();assert_eq!(original.as_ptr(),source_pointer);let mut output=[0;3];output.copy_from_slice(original);assert_eq!(output,[81,82,83]);cx.consume_fuel(4);cx.consume_retained(RetainedCloneProgress{copied_items:2,copied_bytes:3,..Default::default()})?;Err::<(),_>(error.take().unwrap())}));assert_eq!(heap,(0,0));assert!(!witness.is_null());assert!(matches!(call.result,Err(OriginalActorEntryFailure::Semantic)));assert_eq!(guest.original_value_fault().unwrap().message.as_ptr(),cause_pointer);assert_eq!(guest.original_value_fault().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(call.work_units_spent,4);assert_eq!(call.receipt_spent,spent);assert_eq!(spent,RetainedCloneProgress{copied_items:2,copied_bytes:3,..Default::default()});host.receive_guest(call.receipt().unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};let original_source=host.take_dispatched_input().unwrap().unwrap();assert_eq!(original_source.as_ptr(),source_pointer);host.receive_next_issued(incoming).unwrap();
 for turn in 0..100000{let checked=host.checkout_guest(policy).unwrap().unwrap();let mut recipient=Default::default();let(call,system)=observe(||guest.close_jobs_step(checked,StepBudget::new(11,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,&mut provider));let receipt=call.receipt().unwrap();assert_eq!(system,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));allocated+=system.0;released+=system.1;assert_eq!(guest.original_value_fault().unwrap().message.as_ptr(),cause_pointer);let complete=call.result.unwrap();host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();if complete{assert!(!semio_framework_plugin_reactor_jobs::has_owned_jobs(71,3));assert!(!guest.has_original_job_output());break}assert!(turn<99999,"original failed actor job cleanup stalled")}
 let(mut source_close,heap)=observe(||ControlledRetirement::new(original_source).unwrap_or_else(|_|panic!("original job source retirement refused")));allocated+=heap.0;released+=heap.1;
 for turn in 0..100000{if source_close.terminal_is_empty(){break}let checked=host.checkout_guest(policy).unwrap().unwrap();let(step,heap)=observe(||source_close.step(checked.grant));let receipt=checked.return_original(step.unwrap().progress()).unwrap();assert_eq!(heap,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));allocated+=heap.0;released+=heap.1;host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();assert!(turn<99999,"original job source close stalled")}
 assert_eq!(observe(||drop(source_close)).1,(0,0));for turn in 0..100000{if guest.terminal_is_empty(){break}let checked=host.checkout_guest(policy).unwrap().unwrap();let(call,heap)=observe(||guest.close_step(checked));let receipt=call.receipt().unwrap();assert!(call.result.is_ok());assert_eq!(heap,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));allocated+=heap.0;released+=heap.1;host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();assert!(turn<99999,"original job value cause/context close stalled")}
 assert_eq!(allocated,released);assert_eq!(observe(||drop(guest)).1,(0,0));assert_eq!(observe(||drop(host)).1,(0,0));
}
